effect.shader:
const vec3 L = vec3(0.2126,0.7152,0.0722);
vec3 bright(vec4 c){ float y=dot(c.rgb,L); float b=max(y-threshold,0.0)+smoothstep(threshold-knee,threshold+knee,y)*knee; return c.rgb*(b/max(y,0.0001)); }
void main(){ vec2 uv=acScreenNorm; vec2 p=radius/max(inputImg.size,vec2(1.0)); vec4 src=texture2DCv(inputImg.texture,uv); vec3 b=bright(src)*0.20;
b+=(bright(texture2DCv(inputImg.texture,uv+vec2(p.x,0.0)))+bright(texture2DCv(inputImg.texture,uv-vec2(p.x,0.0))))*0.12;
b+=(bright(texture2DCv(inputImg.texture,uv+vec2(0.0,p.y)))+bright(texture2DCv(inputImg.texture,uv-vec2(0.0,p.y))))*0.12;
b+=(bright(texture2DCv(inputImg.texture,uv+p))+bright(texture2DCv(inputImg.texture,uv-p))+bright(texture2DCv(inputImg.texture,uv+vec2(p.x,-p.y)))+bright(texture2DCv(inputImg.texture,uv+vec2(-p.x,p.y))))*0.08;
gl_FragColor=vec4(src.rgb+b*intensity,src.a);
}
